begin; do $$ declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); ra jsonb; rb jsonb; rid uuid; mid uuid:=gen_random_uuid(); begin insert into auth.users(id) values(a),(b); perform set_config('request.jwt.claim.sub',a::text,true); ra:=public.find_versus_opponent('Prueba Aren'); if not (ra->>'waiting')::boolean then raise exception 'not waiting'; end if; perform set_config('request.jwt.claim.sub',b::text,true); rb:=public.find_versus_opponent('Prueba Shadow'); rid:=(rb->>'room_id')::uuid; if rid is null then raise exception 'not matched'; end if; perform set_config('request.jwt.claim.sub',a::text,true); ra:=public.find_versus_opponent('Prueba Aren'); if (ra->>'room_id')::uuid<>rid then raise exception 'different rooms'; end if; ra:=public.find_versus_opponent('Prueba Aren'); if (ra->>'room_id')::uuid<>rid then raise exception 'retry failed'; end if; insert into public.versus_matches(id,room_id,started_at,deadline_at) values(mid,rid,now(),now()+interval '5 minutes'); update public.versus_matches set status='finished',winner_id=a where id=mid; update public.versus_matches set status='finished' where id=mid; if (select count(*) from versus_private.ranked_results where match_id=mid)<>2 then raise exception 'duplicate results'; end if; if (select points from versus_private.ranked_results where match_id=mid and user_id=a)<>3 then raise exception 'wrong points'; end if; delete from public.versus_rooms where id=rid; if (select count(*) from versus_private.ranked_results where match_id=mid)<>2 then raise exception 'lost ranking'; end if; ra:=public.get_versus_ranking(); if jsonb_array_length(ra)<2 then raise exception 'ranking missing'; end if; ra:=public.find_versus_opponent('Prueba Aren'); ra:=public.find_versus_opponent('Prueba Aren',true); if exists(select 1 from versus_private.search_queue where user_id=a) then raise exception 'cancel failed'; end if; end $$; select 'PASS pair, retry, cancel, points, deduplication, durable ranking' as result; rollback;
